// Derive a new (seed, offset) key from 4 random uint32 values.
// Use 2 uint32s for the 64-bit seed and 2 for the 64-bit offset.
__device__ __forceinline__ void philox_derive_key(
    uint4 r,
    uint64_t* out_seed,
    uint64_t* out_offset) {
